const token = 'Your-API-Token-Here';
const newItems = [];
for (const item of items) {
    const html = item.json.html || '';
    const reportTitle = item.json.report_title || 'Executive Report';
    const fileName = reportTitle.replace(/\s+/g, '_') + '.html';
    const htmlBase64 = Buffer.from(html).toString('base64');
    const body = {
        Parameters: [
            {
                Name: 'File',
                FileValue: {
                    Name: fileName,
                    Data: htmlBase64,
                },
            },
            {
                Name: 'PageSize',
                Value: 'Letter',
            },
            {
                Name: 'PageOrientation',
                Value: 'Portrait',
            },
        ],
    };
    const response = await this.helpers.httpRequest({
        method: 'POST',
        url: 'https://v2.convertapi.com/convert/html/to/pdf',
        headers: {
            Authorization: `Bearer ${token}`,
        },
        body,
        json: true,
    });
    if (response.Files && response.Files.length > 0) {
        item.json.pdfFileName = response.Files[0].FileName || 'report.pdf';
        item.json.pdfBase64 = response.Files[0].FileData || null;
        if (response.Files[0].Url) {
            item.json.pdfUrl = response.Files[0].Url;
        }
    } else {
        item.json.error = response;
    }
    newItems.push(item);
}
return newItems;

// Enhance table styling for the executive report
const results = items.map(item => {
  const reportTitle = item.json.report_title || 'Executive Report';
  let htmlString = item.json.html || '';
  // CSS styling including improved table formatting
  const styles = `
    <style>
      body { font-family: Arial, sans-serif; margin: 1in; }
      h1 { text-align: center; font-size: 24pt; margin-bottom: 0.5in; }
      h2, h3 { font-weight: bold; margin-top: 0.5in; }
      p { line-height: 1.5; font-size: 12pt; }
      table { width: 100%; border-collapse: collapse; table-layout: fixed; }
      thead th { background-color: #f2f2f2; }
      th, td { border: 1px solid #ddd; padding: 5px; font-size: 10pt; text-align: left; vertical-align: top; word-wrap: break-word; }
      footer { position: fixed; bottom: 0.5in; left: 0; right: 0; text-align: center; font-size: 10pt; color: #888; }
    </style>
  `;
  // Insert CSS into <head>
  if (/<head\s*>/i.test(htmlString)) {
    htmlString = htmlString.replace(/<head\s*>/i, `<head>${styles}`);
  } else {
    htmlString = `<head>${styles}</head>` + htmlString;
  }
  // Add report title if not present
  if (!/<h1>/i.test(htmlString)) {
    htmlString = htmlString.replace(/<body\s*>/i, `<body><h1>${reportTitle}</h1>`);
  }
  // Append footer with page numbers for PDF.co
  htmlString += `<footer><span class="pageNumber"></span> / <span class="totalPages"></span></footer>`;
  item.json.html = htmlString;
  item.json.report_title = reportTitle;
  return item;
});
return results;
